SELECT channel, CASE WHEN status IN ('COMPLETED', 'RETURNED') THEN 'tier_1' ELSE 'other' END AS status_group, MIN(shipping_fee) AS min_shipping_fee, SUM(CASE WHEN status = 'RETURNED' THEN discount ELSE 0 END) AS returned_discount FROM orders WHERE NOT (status IN ('SHIPPED', 'COMPLETED') AND discount > 0.11) GROUP BY ROLLUP(channel, CASE WHEN status IN ('COMPLETED', 'RETURNED') THEN 'tier_1' ELSE 'other' END) ORDER BY status_group;
